import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices, vatSummary } from '../src/reports.js';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('overdueInvoices returns empty array when none are overdue', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET30',
  });

  const r2 = issueInvoice(r.value, []);

  const overdue = overdueInvoices([r2.value], '2026-11-05');

  assert.equal(overdue.length, 0);
});

test('overdueInvoices includes invoice past due date', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  const r2 = issueInvoice(r.value, []);

  const overdue = overdueInvoices([r2.value], '2026-10-22');

  assert.equal(overdue.length, 1);
  assert.equal(overdue[0].number, r2.value.number);
});

test('overdueInvoices calculates days overdue correctly', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  const r2 = issueInvoice(r.value, []);

  const overdue = overdueInvoices([r2.value], '2026-10-25');

  assert.equal(overdue.length, 1);
  assert.equal(overdue[0].daysOverdue, 4);
});

test('overdueInvoices excludes draft invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  const overdue = overdueInvoices([r.value], '2026-10-25');

  assert.equal(overdue.length, 0);
});

test('overdueInvoices excludes paid invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  const r2 = issueInvoice(r.value, []);
  const totals = invoiceTotals(r2.value);
  const r3 = recordPayment(r2.value, { amount: totals.total, date: '2026-10-08' });

  const overdue = overdueInvoices([r3.value], '2026-10-25');

  assert.equal(overdue.length, 0);
});

test('overdueInvoices includes partially_paid invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  const r2 = issueInvoice(r.value, []);
  const r3 = recordPayment(r2.value, { amount: 1000, date: '2026-10-08' });

  const overdue = overdueInvoices([r3.value], '2026-10-25');

  assert.equal(overdue.length, 1);
  assert(overdue[0].due > 0);
});

test('overdueInvoices shows correct due amount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  const r2 = issueInvoice(r.value, []);
  const totals = invoiceTotals(r2.value);
  const r3 = recordPayment(r2.value, { amount: 1000, date: '2026-10-08' });

  const overdue = overdueInvoices([r3.value], '2026-10-25');

  assert.equal(overdue.length, 1);
  assert.equal(overdue[0].due, totals.total - 1000);
});

test('overdueInvoices sorts by days overdue descending', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET30',
  });

  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET30',
  });

  const r3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-09-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET30',
  });

  const r1i = issueInvoice(r1.value, []);
  const r2i = issueInvoice(r2.value, []);
  const r3i = issueInvoice(r3.value, []);

  const overdue = overdueInvoices([r1i.value, r2i.value, r3i.value], '2026-11-15');

  assert.equal(overdue.length, 3);
  assert(overdue[0].daysOverdue >= overdue[1].daysOverdue);
  assert(overdue[1].daysOverdue >= overdue[2].daysOverdue);
  assert.equal(overdue[0].daysOverdue, 45);
  assert.equal(overdue[1].daysOverdue, 31);
  assert.equal(overdue[2].daysOverdue, 15);
});

test('overdueInvoices with multiple customers', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  const r1i = issueInvoice(r1.value, []);
  const r2i = issueInvoice(r2.value, []);

  const overdue = overdueInvoices([r1i.value, r2i.value], '2026-10-25');

  assert.equal(overdue.length, 2);
  assert.equal(overdue[0].customerId, 'C-001');
  assert.equal(overdue[1].customerId, 'C-002');
});

test('overdueInvoices shows invoice number and due date', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  const r2 = issueInvoice(r.value, []);

  const overdue = overdueInvoices([r2.value], '2026-10-25');

  assert.equal(overdue.length, 1);
  assert.equal(overdue[0].number, r2.value.number);
  assert.equal(overdue[0].dueDate, '2026-10-21');
});

test('overdueInvoices with empty invoice list', () => {
  const overdue = overdueInvoices([], '2026-10-25');

  assert.equal(overdue.length, 0);
});

test('overdueInvoices excludes invoices due on asOf date', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  const r2 = issueInvoice(r.value, []);

  const overdue = overdueInvoices([r2.value], '2026-10-21');

  assert.equal(overdue.length, 0);
});

test('overdueInvoices includes invoices due yesterday', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  const r2 = issueInvoice(r.value, []);

  const overdue = overdueInvoices([r2.value], '2026-10-22');

  assert.equal(overdue.length, 1);
  assert.equal(overdue[0].daysOverdue, 1);
});

test('overdueInvoices with EOM terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'EOM',
  });

  const r2 = issueInvoice(r.value, []);

  const overdue = overdueInvoices([r2.value], '2026-11-01');

  assert.equal(overdue.length, 1);
  assert.equal(overdue[0].daysOverdue, 1);
});

test('overdueInvoices with multiple invoices mixed statuses', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  const r3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const r1i = issueInvoice(r1.value, []);
  const r2i = issueInvoice(r2.value, []);
  const r2p = recordPayment(r2i.value, { amount: 1000, date: '2026-10-09' });

  const overdue = overdueInvoices([r1i.value, r2p.value, r3.value], '2026-10-25');

  assert.equal(overdue.length, 2);
  assert.equal(overdue[0].number, r1i.value.number);
